head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods90006";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods90006.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods90006.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name area_5_onclick
 * @description area_5 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.area_5_onclick = function(e){
    try {
        scwin.fnPopLink()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods90006.area_5_onclick' }); }
};

/**
 * @method
 * @name btn_eClose_onclick
 * @description btn_eClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_eClose_onclick = function(e){
    try {
        scwin.e_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods90006.btn_eClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCookie
 * @description set Cookie 처리
 * @param {*} name name
 * @param {*} value value
 * @param {*} expiredays expiredays
 * @returns {void}
 * @hidden N
 */
scwin.setCookie = function (name, value, expiredays) { $c.util.setSessionStorage(name, value); };

/**
 * @method
 * @name e_close
 * @description e close 처리
 * @returns {void}
 * @hidden N
 */
scwin.e_close = function () {
    if ($("#ipt_todayNot").is(":checked")) {
        scwin.setCookie("JLDODS90006", "JLDODS90006", 1);
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name fnPopLink
 * @description fn Pop Link 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPopLink = function () {
    (Promise.resolve($c.win.openPopup("/pop_tls_info/pop_tls_info.xml", { id: "_blank", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("_blank"); this.closed = true; } });
    $c.win.closePopup();
};
